import{c as a,Q as t,j as o,m as s}from"./chunks/framework.g_l1frA7.js";const g=JSON.parse('{"title":"Today","description":"","frontmatter":{},"headers":[],"relativePath":"guide/today.md","filePath":"guide/today.md","lastUpdated":null}'),i={name:"guide/today.md"};function n(r,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="today" tabindex="-1">Today <a class="header-anchor" href="#today" aria-label="Permalink to &quot;Today&quot;">​</a></h1><p>Today is the anchoring screen — one place that answers “Where do I stand?” and “What’s the one thing to do today?”</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><ul><li><strong>Net worth + trend</strong> — sum of asset accounts minus liabilities, with a sparkline from balance history. Derived from transactions and stored balances; no manual double-entry.</li><li><strong>Income / Expenses / Savings rate</strong> — this month’s totals and the savings-rate gauge. Pay Yourself First is healthy at ≥10%.</li><li><strong>Category stream</strong> — a thin allocation bar where each segment is a category’s share of spend. Source: this month’s categorized transactions.</li><li><strong>Progress &amp; More (collapsible)</strong> — secondary metrics (emergency-fund months, snowball, allocation donut) live inside disclosure panels so the primary panel reads as one instrument.</li><li><strong>Next action</strong> — the Copilot’s highest-priority nudge (e.g. “Fund your emergency reserve before ambitious saving”) with a direct link.</li></ul><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>All figures use the <code>money</code> class. Toggle the eye icon — numbers blur and tooltips hide amounts.</p><h2 id="where-numbers-come-from" tabindex="-1">Where numbers come from <a class="header-anchor" href="#where-numbers-come-from" aria-label="Permalink to &quot;Where numbers come from&quot;">​</a></h2><p><code>finsight-core::metrics</code> computes net/income/expenses and <code>wellness_context</code> computes emergency-fund months, snowball order, and allocation. The Today view reuses whatever <code>wellness_context</code> the Copilot would see, so totals never disagree between Today and the Copilot.</p><h2 id="what-to-do" tabindex="-1">What to do <a class="header-anchor" href="#what-to-do" aria-label="Permalink to &quot;What to do&quot;">​</a></h2><ul><li>If savings rate &lt; 10%, open <a href="/FinSight/guide/budget">Budget</a> and move one envelope toward Saving.</li><li>If a subscription anomaly is flagged, check <a href="/FinSight/guide/insights">Insights</a>.</li><li>Ask the Copilot: “Why is my savings rate down this month?” — it cites the same metrics with inputs and exclusions.</li></ul><p>See also: <a href="/FinSight/guide/insights">Insights</a>, <a href="/FinSight/guide/budget">Budget</a>, <a href="/FinSight/guide/goals">Goals</a>.</p>',11)])])}const m=a(i,[["render",n]]);export{g as __pageData,m as default};
